296			t.Fatalf("common source order = %v, want %v", got, want)
297		}
298		assertEachCommonOnce(t, found)
299	}
300	
301	// The two sides can have different distances and different explanation paths:
302	// each side is traced independently from its own target.
303	func TestCommonUpstreamsAsymmetricSides(t *testing.T) {
304		// shared reaches left over one hop and right over a longer detour.
305		graph := buildRegisteredGraph(t, [][]string{
306			{"shared"},
307			{"x", "shared"},
308			{"left", "shared"},
309			{"right", "x"},
310		})
311	
312		found := mustCommon(t, graph, "left", "right")
313		if got, want := commonNames(found), []string{"shared"}; !reflect.DeepEqual(got, want) {
314			t.Fatalf("common sources = %v, want %v", got, want)
315		}
316		assertCommon(t, found, "shared",
317			1, []string{"shared", "left"},
318			2, []string{"shared", "x", "right"})
319	
320		// Swapping the query swaps both sides field by field.
321		found = mustCommon(t, graph, "right", "left")
322		assertCommon(t, found, "shared",
323			2, []string{"shared", "x", "right"},
324			1, []string{"shared", "left"})
325	}
326	
327	// Among equally short routes on one side, the full-path lexicographic rule used
328	// by Upstreams applies: compare name by name from the source, not just the
329	// target's direct upstream.
330	func TestCommonUpstreamsFullPathTieBreak(t *testing.T) {
331		// left reaches the shared root through a->z and b->c (both length 3);
332		// right depends on the root alone. The shared frontier is the root, and its
333		// path toward left must be the a/z route because a < b at hop 1.
334		graph := buildRegisteredGraph(t, [][]string{
335			{"source"},
336			{"b", "source"}, // b-side registered first on purpose
337			{"a", "source"},
338			{"c", "b"},
339			{"z", "a"},
340			{"left", "c", "z"},
341			{"right", "source"},
342		})
343	
344		found := mustCommon(t, graph, "left", "right")
345		if got, want := commonNames(found), []string{"source"}; !reflect.DeepEqual(got, want) {
346			t.Fatalf("common sources = %v, want %v", got, want)
347		}
348		assertCommon(t, found, "source",
349			3, []string{"source", "a", "z", "left"},
350			1, []string{"source", "right"})
351	}
352	
353	// Paths are computed against the current edges: replacing a direct upstream
354	// lengthens the distance and re-derives the explanation on that side, while
355	// the other side and the frontier membership stay consistent.
356	func TestCommonUpstreamsReflectReregister(t *testing.T) {
357		graph := buildRegisteredGraph(t, [][]string{
358			{"raw"},
359			{"a", "raw"},
360			{"left", "raw", "a"},
361			{"right", "raw"},
362		})
363	
364		// Initially raw is a direct parent of both, but a is a later common source
365		// on the left side only: a is not upstream of right, so raw is the sole
366		// frontier (a is not even common).
367		found := mustCommon(t, graph, "left", "right")
368		if got, want := commonNames(found), []string{"raw"}; !reflect.DeepEqual(got, want) {
369			t.Fatalf("common sources = %v, want %v", got, want)
370		}
371		assertCommon(t, found, "raw", 1, []string{"raw", "left"}, 1, []string{"raw", "right"})
372	
373		// right now also derives through a: a becomes the later common source and
374		// raw is hidden, even though the direct raw edges remain.
375		mustRegister(t, graph, "right", "raw", "a")
376		found = mustCommon(t, graph, "left", "right")
377		if got, want := commonNames(found), []string{"a"}; !reflect.DeepEqual(got, want) {
378			t.Fatalf("after rewire common sources = %v, want %v", got, want)
379		}
380		assertCommon(t, found, "a", 1, []string{"a", "left"}, 1, []string{"a", "right"})
381	}
382	
383	// Registration order and stored upstream-list order must not change results:
384	// two builds of the same graph with shuffled orders agree exactly.
385	func TestCommonUpstreamsOrderInvariance(t *testing.T) {
386		builds := []map[string]*Lineage{
387			buildRegisteredGraph(t, [][]string{
388				{"raw"},
389				{"b", "raw"}, // b-side first
390				{"a", "raw"},
391				{"right", "b", "a"}, // list order disagrees with name order
392				{"left", "a", "b"},
393			}),
394			buildRegisteredGraph(t, [][]string{
395				{"raw"},
396				{"a", "raw"},
397				{"b", "raw"},
398				{"left", "b", "a"},
399				{"right", "a", "b"},
400			}),
401		}
402	
403		first := mustCommon(t, builds[0], "left", "right")
404		second := mustCommon(t, builds[1], "left", "right")
405		if !reflect.DeepEqual(first, second) {
406			t.Fatalf("equivalent graphs differ: %v vs %v", first, second)
407		}
408		if got, want := commonNames(first), []string{"a", "b"}; !reflect.DeepEqual(got, want) {
409			t.Fatalf("common sources = %v, want %v", got, want)
410		}
411	}
412	
413	// Targets are validated in input order: first target first, then second.
414	func TestCommonUpstreamsValidationOrder(t *testing.T) {
415		graph := buildRegisteredGraph(t, [][]string{{"a"}})
416	
417		// Empty first target reports the missing name before the second is looked
418		// at, even though the second is also invalid.
419		found, err := CommonUpstreams(graph, "", "ghost")
420		if err == nil || !strings.Contains(err.Error(), "name is required") {
421			t.Fatalf("empty first: want required-name error, got %v", err)
422		}
423		if found != nil {
424			t.Fatalf("empty first: want nil results, got %v", found)
425		}
426	
427		// Unregistered first target reports that name before an invalid second.
428		found, err = CommonUpstreams(graph, "ghost", "")
429		if err == nil || !strings.Contains(err.Error(), "ghost") {
430			t.Fatalf("unknown first: want error naming ghost, got %v", err)
431		}
432		if found != nil {
433			t.Fatalf("unknown first: want nil results, got %v", found)
434		}
435	
436		// Valid first, empty second.
437		found, err = CommonUpstreams(graph, "a", "")
438		if err == nil || !strings.Contains(err.Error(), "name is required") {
439			t.Fatalf("empty second: want required-name error, got %v", err)
440		}
441		if found != nil {
442			t.Fatalf("empty second: want nil results, got %v", found)
443		}
444	
445		// Valid first, unregistered second: error names the second target.
446		found, err = CommonUpstreams(graph, "a", "ghost")
447		if err == nil || !strings.Contains(err.Error(), "ghost") {
448			t.Fatalf("unknown second: want error naming ghost, got %v", err)
449		}
450		if found != nil {
451			t.Fatalf("unknown second: want nil results, got %v", found)
452		}
453	}
454	
455	// Empty and nil graphs behave like unregistered-name errors for non-empty
456	// targets, and an empty name is still a missing-name error.
457	func TestCommonUpstreamsEmptyAndNilGraph(t *testing.T) {
458		for name, graph := range map[string]map[string]*Lineage{
459			"empty": {},
460			"nil":   nil,
461		} {
462			found, err := CommonUpstreams(graph, "x", "y")
463			if err == nil || !strings.Contains(err.Error(), "x") {
464				t.Fatalf("%s graph: want error naming first target x, got %v", name, err)
465			}
466			if found != nil {
467				t.Fatalf("%s graph: want nil results, got %v", name, found)
468			}
469	
470			// Empty first name against an empty/nil graph is still the missing-name
471			// error, never a not-found error.
472			found, err = CommonUpstreams(graph, "", "y")
473			if err == nil || !strings.Contains(err.Error(), "name is required") {
474				t.Fatalf("%s graph, empty first: want required-name error, got %v", name, err)
475			}
476			if found != nil {
477				t.Fatalf("%s graph, empty first: want nil results, got %v", name, found)
478			}
479		}
480	}
481	
482	// Names match by exact registered value, case-sensitive.
483	func TestCommonUpstreamsExactNameMatch(t *testing.T) {
484		graph := buildRegisteredGraph(t, [][]string{
485			{"raw"},
486			{"RAW", "raw"},
487			{"raw-other", "raw"},
488		})
489	
490		if _, err := CommonUpstreams(graph, "RaW", "raw"); err == nil ||
491			!strings.Contains(err.Error(), "RaW") {
492			t.Fatalf("case-insensitive first target: want error naming RaW, got %v", err)
493		}
494		if _, err := CommonUpstreams(graph, "RAW", "raW"); err == nil ||
495			!strings.Contains(err.Error(), "raW") {
496			t.Fatalf("case-insensitive second target: want error naming raW, got %v", err)
497		}
498	
499		// RAW and raw-other share only raw; the differently-cased names are distinct.
500		found := mustCommon(t, graph, "RAW", "raw-other")
501		if got, want := commonNames(found), []string{"raw"}; !reflect.DeepEqual(got, want) {
502			t.Fatalf("common sources = %v, want %v", got, want)
503		}
504		assertCommon(t, found, "raw", 1, []string{"raw", "RAW"}, 1, []string{"raw", "raw-other"})
505	}
506	
507	// A query never mutates the graph, and mutating returned records or paths can
508	// reach neither the graph, the other side's path, other records, nor later
509	// queries.
510	func TestCommonUpstreamsReadOnlyAndIsolated(t *testing.T) {
511		graph := buildRegisteredGraph(t, [][]string{
512			{"raw"},
513			{"a", "raw"},
514			{"b", "raw"},
515			{"x", "a"},
516			{"left", "a", "b"},
517			{"right", "b", "x"},
518		})
519		before := snapshot(graph)
520	
521		found, err := CommonUpstreams(graph, "left", "right")
522		if err != nil {
523			t.Fatalf("CommonUpstreams: %v", err)
524		}
525		if !reflect.DeepEqual(snapshot(graph), before) {
526			t.Fatalf("query changed graph: before=%v after=%v", before, snapshot(graph))
527		}
528	
529		// Abuse every returned slice, then confirm the graph and a repeat query are
530		// untouched and the two sides did not share storage.
531		found[0].PathToFirst[0] = "tampered-1"
532		found[0].PathToFirst = append(found[0].PathToFirst, "extra")
533		found[0].PathToSecond[0] = "tampered-2"
534		found[0].Dataset = "tampered"
535		found[0].DistanceToFirst = 99
536		found[0].DistanceToSecond = 99
537		if !reflect.DeepEqual(snapshot(graph), before) {
538			t.Fatalf("mutating results changed graph: before=%v after=%v", before, snapshot(graph))
539		}
540	
541		// A failed query is also read-only.
542		if _, err := CommonUpstreams(graph, "missing", "left"); err == nil {
543			t.Fatal("expected not-found error for first target")
544		}
545		if _, err := CommonUpstreams(graph, "left", "missing"); err == nil {
546			t.Fatal("expected not-found error for second target")
547		}
548		if !reflect.DeepEqual(snapshot(graph), before) {
549			t.Fatalf("failed queries changed graph: before=%v after=%v", before, snapshot(graph))
550		}
551		assertConsistent(t, graph)
552	
553		// A repeat query still returns the original, un-tampered content.
554		fresh := mustCommon(t, graph, "left", "right")
555		for _, c := range fresh {
556			for _, step := range append(append([]string(nil), c.PathToFirst...), c.PathToSecond...) {
557				if strings.Contains(step, "tampered") {
558					t.Fatalf("tampered path leaked into fresh query: %v", fresh)
559				}
560			}
561			if c.Dataset == "tampered" || c.DistanceToFirst == 99 || c.DistanceToSecond == 99 {
562				t.Fatalf("tampered record leaked into fresh query: %v", fresh)
563			}
564		}
565	}
566	
567	// A result taken before a re-registration keeps its original paths; only a
568	// re-query reflects the new edges.
569	func TestCommonUpstreamsOldResultStableAfterReregister(t *testing.T) {
570		graph := buildRegisteredGraph(t, [][]string{
571			{"raw"},
572			{"a", "raw"},
573			{"b", "raw"},
574			{"left", "a", "b"},
575			{"right", "a", "b"},
576		})
577	
578		before := mustCommon(t, graph, "left", "right")
579		beforeCopy := make([]CommonUpstream, len(before))
580		for i, c := range before {
581			beforeCopy[i] = CommonUpstream{
582				Dataset:          c.Dataset,
583				DistanceToFirst:  c.DistanceToFirst,
584				PathToFirst:      append([]string(nil), c.PathToFirst...),
585				DistanceToSecond: c.DistanceToSecond,
586				PathToSecond:     append([]string(nil), c.PathToSecond...),
587			}
588		}
589	
590		mustRegister(t, graph, "right", "a")
591		if !reflect.DeepEqual(before, beforeCopy) {
592			t.Fatalf("earlier result changed after re-register: before=%v snapshot=%v",
593				before, beforeCopy)
594		}
595	}
596	
597	// Every returned path starts with the source and ends at the queried target,
598	// and its length matches the reported distance plus one.
599	func TestCommonUpstreamsPathShape(t *testing.T) {
600		graph := buildRegisteredGraph(t, [][]string{
601			{"r"},
602			{"a", "r"},
603			{"b", "a"},
604			{"left", "b"},
605			{"x", "r"},
606			{"right", "x", "b"},
607		})
608	
609		found := mustCommon(t, graph, "left", "right")
610		for _, c := range found {
611			if c.PathToFirst[0] != c.Dataset || c.PathToFirst[len(c.PathToFirst)-1] != "left" {
612				t.Errorf("source %s path-to-first = %v must run from source to left", c.Dataset, c.PathToFirst)
613			}
614			if c.PathToSecond[0] != c.Dataset || c.PathToSecond[len(c.PathToSecond)-1] != "right" {
615				t.Errorf("source %s path-to-second = %v must run from source to right", c.Dataset, c.PathToSecond)
616			}
617			if len(c.PathToFirst) != c.DistanceToFirst+1 {
618				t.Errorf("source %s first path length %d != distance %d+1",
619					c.Dataset, len(c.PathToFirst), c.DistanceToFirst)
620			}
621			if len(c.PathToSecond) != c.DistanceToSecond+1 {
622				t.Errorf("source %s second path length %d != distance %d+1",
623					c.Dataset, len(c.PathToSecond), c.DistanceToSecond)
624			}
625		}
626	}
