3	import (
4		"reflect"
5		"slices"
6		"sort"
7		"strings"
8		"testing"
9	)
10	
11	// This file is the regression guard for the relationship between the scoped
12	// lineage export and the two directional queries, as the queried source and
13	// target change within one registered graph:
14	//
15	//   - ExportSourceTargetLineage keeps EVERY existing route between the two
16	//     endpoints (all branches), while Impacts and Upstreams each explain a
17	//     reachable dataset with exactly one shortest, tie-broken path.
18	//   - For one pair of distinct, genuinely connected endpoints, the downstream
19	//     row Impacts(source) carries for target and the upstream row
20	//     Upstreams(target) carries for source must agree on distance and path, and
21	//     that explanation must be fully present inside the export — while the
22	//     export additionally keeps the routes the explanation path did not pick.
23	//
24	// Every expectation here is derived independently by enumerating simple walks
25	// over the stored parent edges (a route witness), never from the production
26	// traversals, so a wrong branch/edge selection in the export itself is caught.
27	
28	// correspondenceFixtureRegistrations builds a registered acyclic graph with
29	// successive forks and merges, routes of different lengths sharing segments,
30	// a direct source->target edge, an intermediate dataset with an independent
31	// second source, a source downstream that cannot reach the target, and the
32	// target's own downstream:
33	//
34	//	extra ──┐ (a's independent source, not downstream of src)
35	//	        v
36	//	src ──┬─> a ──> g ──┬──────────────┐
37	//	  │   │      │      └─> d ──> m <───┘ (g -> m is also direct)
38	//	  │   │      └──────────────> report  (direct a -> report too)
39	//	  ├─> b ──┬─> c ───────────> m ─> report
40	//	  │       └─> d  (d merges b and g)
41	//	  ├─> report                  (direct src -> report)
42	//	  ├─> dead                    (src downstream that never reaches report)
43	//	  └─(report -> view)          (target's own downstream)
44	//
45	// src therefore reaches report six ways at once: directly (1 edge), through
46	// a (2 edges), through a -> g -> m (4 edges), through b -> c -> m and
47	// b -> d -> m (4 edges), and through a -> g -> d -> m (5 edges).
48	func correspondenceFixtureRegistrations() [][]string {
49		return [][]string{
50			{"src"},
51			{"extra"},
52			{"a", "src", "extra"},
53			{"b", "src"},
54			{"g", "a"},
55			{"c", "b"},
56			{"d", "b", "g"},
57			{"m", "c", "d", "g"},
58			{"report", "src", "a", "m"},
59			{"dead", "src"},
60			{"view", "report"},
61		}
62	}
63	
64	// enumerateSourceTargetRoutes returns every simple walk from source to target
65	// over registered child edges, each including both ends. Expansion stops at
66	// target, so target's downstream cannot enter a route. Register rejects
67	// cycles, so the simple-walk search terminates.
68	func enumerateSourceTargetRoutes(t *testing.T, graph map[string]*Lineage, source, target string) [][]string {
69		t.Helper()
70		var routes [][]string
71		seen := map[string]bool{source: true}
72		var walk func(path []string)
73		walk = func(path []string) {
74			cur := path[len(path)-1]
75			if cur == target {
76				routes = append(routes, append([]string(nil), path...))
77				return
78			}
79			for _, next := range graph[cur].Children {
80				if seen[next] {
81					continue
82				}
83				seen[next] = true
84				walk(append(path, next))
85				delete(seen, next)
86			}
87		}
88		walk([]string{source})
89		return routes
90	}
91	
92	// expectedScopedDocument derives the scoped export independently from the
93	// route witness: one node per dataset appearing on at least one source ->
94	// target route, one edge per consecutive dependency carried by any such
95	// route, presented in the public ordering (nodes by name, edges by from then
96	// to).
97	func expectedScopedDocument(t *testing.T, graph map[string]*Lineage, source, target string) ([]string, [][2]string) {
98		t.Helper()
99		nodeSet := map[string]bool{}
100		edgeSet := map[[2]string]bool{}
101		for _, route := range enumerateSourceTargetRoutes(t, graph, source, target) {
102			for i, name := range route {
103				nodeSet[name] = true
104				if i+1 < len(route) {
105					edgeSet[[2]string{route[i], route[i+1]}] = true
106				}
107			}
108		}
109		nodes := make([]string, 0, len(nodeSet))
110		for name := range nodeSet {
111			nodes = append(nodes, name)
112		}
113		sort.Strings(nodes)
114		edges := make([][2]string, 0, len(edgeSet))
115		for edge := range edgeSet {
116			edges = append(edges, edge)
117		}
118		sort.Slice(edges, func(i, j int) bool {
119			if edges[i][0] != edges[j][0] {
120				return edges[i][0] < edges[j][0]
121			}
122			return edges[i][1] < edges[j][1]
123		})
124		return nodes, edges
125	}
126	
127	// assertScopedExportShape pins the public document behavior directly:
128	//
129	//   - nodes are unique and in Go string order, edges unique and ordered by
130	//     (from, to);
131	//   - every endpoint and every dependency is a registered edge pointing in the
132	//     derivation direction (from is a direct upstream of to), and every edge
133	//     joins two documented nodes;
134	//   - a document with no routes (or the single-node document) carries empty
135	//     arrays, not null.
136	func assertScopedExportShape(t *testing.T, graph map[string]*Lineage, doc exportDocument) {
137		t.Helper()
138		if doc.Nodes == nil {
139			t.Fatalf("nodes must be a non-nil JSON array in %+v", doc)
140		}
141		if doc.Edges == nil {
142			t.Fatalf("edges must be a non-nil JSON array in %+v", doc)
143		}
144		if !slices.IsSorted(doc.Nodes) {
145			t.Errorf("nodes are not in Go string order: %v", doc.Nodes)
146		}
147		seenNode := map[string]bool{}
148		for _, name := range doc.Nodes {
149			if seenNode[name] {
150				t.Errorf("node %q appears more than once in %v", name, doc.Nodes)
151			}
152			seenNode[name] = true
153			if _, ok := graph[name]; !ok {
154				t.Errorf("document names unregistered dataset %q", name)
155			}
156		}
157		seenEdge := map[[2]string]bool{}
158		for i, e := range doc.Edges {
159			edge := [2]string{e.From, e.To}
160			if seenEdge[edge] {
161				t.Errorf("edge %s -> %s appears more than once", e.From, e.To)
162			}
163			seenEdge[edge] = true
164			if i > 0 {
165				prev := doc.Edges[i-1]
166				if prev.From > e.From || (prev.From == e.From && prev.To >= e.To) {
167					t.Errorf("edges are not ordered by (from, to) at %d: %s->%s follows %s->%s",
168						i, prev.From, prev.To, e.From, e.To)
169				}
170			}
171			if !seenNode[e.From] || !seenNode[e.To] {
172				t.Errorf("edge %s -> %s joins a node missing from the document: nodes %v",
173					e.From, e.To, doc.Nodes)
174			}
175			derived, ok := graph[e.To]
176			if !ok || !slices.Contains(derived.Parents, e.From) {
177				t.Errorf("edge %s -> %s is not an existing upstream-to-derived dependency", e.From, e.To)
178			}
179		}
180	}
181	
182	// assertPathInsideDocument requires every hop of an explanation path to be a
183	// documented node joined by the documented dependency in derivation order.
184	func assertPathInsideDocument(t *testing.T, doc exportDocument, path []string) {
185		t.Helper()
186		nodes := map[string]bool{}
187		for _, name := range doc.Nodes {
188			nodes[name] = true
189		}
190		edges := map[[2]string]bool{}
191		for _, e := range doc.Edges {
192			edges[[2]string{e.From, e.To}] = true
193		}
194		for i, name := range path {
195			if !nodes[name] {
196				t.Fatalf("explanation path %v uses node %q absent from document nodes %v",
197					path, name, doc.Nodes)
198			}
199			if i+1 < len(path) && !edges[[2]string{path[i], path[i+1]}] {
200				t.Fatalf("explanation path %v uses dependency %s -> %s absent from document edges",
201					path, path[i], path[i+1])
202			}
203		}
204	}
