224	// assertSourceTargetPairContract runs the whole correspondence guard for one
225	// ordered endpoint pair against the route witness:
226	//
227	//  1. the export equals the union of every source -> target route (nodes and
228	//     edges), ordered and directed per the public JSON contract;
229	//  2. for distinct connected endpoints, Impacts(source) finds target and
230	//     Upstreams(target) finds source with the same distance and the same
231	//     source-to-target path, equal to the witness's shortest route, and that
232	//     path exists hop by hop inside the export;
233	//  3. for distinct endpoints with no forward route, both queries deny the
234	//     relation and the export is two empty arrays (a reverse dependency
235	//     included);
236	//  4. for identical endpoints the document is just that node with no edges,
237	//     and neither query lists the node itself.
238	func assertSourceTargetPairContract(t *testing.T, graph map[string]*Lineage, source, target string) {
239		t.Helper()
240		out := mustExportScoped(t, graph, source, target)
241		doc := parseExport(t, out)
242		assertScopedExportShape(t, graph, doc)
243	
244		wantNodes, wantEdges := expectedScopedDocument(t, graph, source, target)
245		if !reflect.DeepEqual(doc.Nodes, wantNodes) {
246			t.Errorf("ExportSourceTargetLineage(%q, %q) nodes = %v, want %v",
247				source, target, doc.Nodes, wantNodes)
248		}
249		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
250			t.Errorf("ExportSourceTargetLineage(%q, %q) edges = %v, want %v",
251				source, target, got, wantEdges)
252		}
253	
254		routes := enumerateSourceTargetRoutes(t, graph, source, target)
255		impacts := mustImpacts(t, graph, source)
256		upstreams := mustUpstreams(t, graph, target)
257	
258		if source == target {
259			if len(doc.Nodes) != 1 || doc.Nodes[0] != source || len(doc.Edges) != 0 {
260				t.Errorf("same endpoint %q export must be the singleton node with no edges, got %v / %v",
261					source, doc.Nodes, exportEdgeNames(doc))
262			}
263			if _, ok := impactRecordFor(impacts, source); ok {
264				t.Errorf("Impacts(%q) must not list the origin itself", source)
265			}
266			if _, ok := upstreamRecordFor(upstreams, target); ok {
267				t.Errorf("Upstreams(%q) must not list the target itself", target)
268			}
269			return
270		}
271	
272		downRow, downOK := impactRecordFor(impacts, target)
273		upRow, upOK := upstreamRecordFor(upstreams, source)
274		if len(routes) == 0 {
275			if len(doc.Nodes) != 0 || len(doc.Edges) != 0 {
276				t.Errorf("(%q, %q) have no forward route: export must be two empty arrays, got %v / %v",
277					source, target, doc.Nodes, exportEdgeNames(doc))
278			}
279			if downOK {
280				t.Errorf("(%q -> %q) is not a forward route but Impacts lists %v", source, target, downRow)
281			}
282			if upOK {
283				t.Errorf("(%q -> %q) is not a forward route but Upstreams(%q) lists %v",
284					source, target, target, upRow)
285			}
286			return
287		}
288	
289		if !downOK {
290			t.Fatalf("Impacts(%q) must find connected target %q", source, target)
291		}
292		if !upOK {
293			t.Fatalf("Upstreams(%q) must find connected source %q", target, source)
294		}
295		if downRow.Distance != upRow.Distance {
296			t.Errorf("distance for %q -> %q disagrees: Impacts %d, Upstreams %d",
297				source, target, downRow.Distance, upRow.Distance)
298		}
299		if !reflect.DeepEqual(downRow.Path, upRow.Path) {
300			t.Errorf("path for %q -> %q disagrees: Impacts %v, Upstreams %v",
301				source, target, downRow.Path, upRow.Path)
302		}
303		if downRow.Distance != len(downRow.Path)-1 {
304			t.Errorf("distance %d does not match path %v edge count",
305				downRow.Distance, downRow.Path)
306		}
307	
308		// Independent shortest witness over the same registered edges.
309		oracle := newLineageTestOracle(t, graph)
310		wantDistance, wantPath, reachable := oracle.shortest(source, target)
311		if !reachable {
312			t.Fatalf("route witness found routes but the shortest-path oracle denies %q -> %q", source, target)
313		}
314		if downRow.Distance != wantDistance || !reflect.DeepEqual(downRow.Path, wantPath) {
315			t.Errorf("query row for %q -> %q = (distance %d, path %v), want (distance %d, path %v)",
316				source, target, downRow.Distance, downRow.Path, wantDistance, wantPath)
317		}
318	
319		// The chosen explanation path must exist completely inside the exported
320		// document, which itself keeps every route — including the unchosen ones.
321		assertPathEdgesRegistered(t, graph, downRow.Path)
322		assertPathInsideDocument(t, doc, downRow.Path)
323		assertImpactListShape(t, graph, source, impacts)
324		assertUpstreamListShape(t, graph, target, upstreams)
325	
326		// Every enumerated route, not only the shortest explanation, must survive
327		// in the document node and edge set; this is the branch-preservation core.
328		for _, route := range routes {
329			assertPathInsideDocument(t, doc, route)
330		}
331	}
