333	// Exhaustive correspondence over every ordered endpoint pair in the forked and
334	// merged graph: changing source and target — including promoting a former
335	// intermediate dataset to an endpoint — must change the export to exactly the
336	// routes that really connect the new pair, and both directional queries must
337	// witness the same shortest explanation inside it.
338	func TestExportSourceTargetLineageCorrespondsWithImpactsAndUpstreams(t *testing.T) {
339		graph := buildRegisteredGraph(t, correspondenceFixtureRegistrations())
340		assertConsistent(t, graph)
341		names := sortedGraphNames(graph)
342		before := snapshot(graph)
343	
344		for _, source := range names {
345			for _, target := range names {
346				assertSourceTargetPairContract(t, graph, source, target)
347			}
348		}
349	
350		// Explicit anchors at the tricky scopes.
351	
352		// The main pair: the direct edge gives the distance-1 explanation from
353		// both queries, yet every longer fork/merge branch stays in the export.
354		mainOut := mustExportScoped(t, graph, "src", "report")
355		mainDoc := parseExport(t, mainOut)
356		mainNodes := []string{"a", "b", "c", "d", "g", "m", "report", "src"}
357		mainEdges := [][2]string{
358			{"a", "g"},
359			{"a", "report"},
360			{"b", "c"},
361			{"b", "d"},
362			{"c", "m"},
363			{"d", "m"},
364			{"g", "d"},
365			{"g", "m"},
366			{"m", "report"},
367			{"src", "a"},
368			{"src", "b"},
369			{"src", "report"},
370		}
371		if !reflect.DeepEqual(mainDoc.Nodes, mainNodes) {
372			t.Errorf("(src, report) nodes = %v, want %v", mainDoc.Nodes, mainNodes)
373		}
374		if got := exportEdgeNames(mainDoc); !reflect.DeepEqual(got, mainEdges) {
375			t.Errorf("(src, report) edges = %v, want %v", got, mainEdges)
376		}
377		// Shared nodes and edges appear once.
378		if len(mainDoc.Nodes) != len(mainNodes) || len(mainDoc.Edges) != len(mainEdges) {
379			t.Errorf("duplicate entries in singleton-checked document: %v / %v", mainDoc.Nodes, exportEdgeNames(mainDoc))
380		}
381		// Unrelated nodes never ride along: the independent source's edge, the
382		// dead-end branch and the target's downstream are all absent.
383		for _, banned := range []string{"extra", "dead", "view"} {
384			if slices.Contains(mainDoc.Nodes, banned) {
385				t.Errorf("(src, report) must not include %q: %v", banned, mainDoc.Nodes)
386			}
387		}
388		for _, banned := range [][2]string{{"extra", "a"}, {"src", "dead"}, {"report", "view"}} {
389			if slices.Contains(exportEdgeNames(mainDoc), banned) {
390				t.Errorf("(src, report) must not carry edge %s -> %s", banned[0], banned[1])
391			}
392		}
393		impacts := mustImpacts(t, graph, "src")
394		upstreams := mustUpstreams(t, graph, "report")
395		assertImpactOnce(t, impacts, "report", 1, []string{"src", "report"})
396		assertUpstreamOnce(t, upstreams, "src", 1, []string{"src", "report"})
397		// The unchosen long routes remain in the document with every hop.
398		for _, route := range [][]string{
399			{"src", "a", "g", "m", "report"},
400			{"src", "b", "c", "m", "report"},
401			{"src", "b", "d", "m", "report"},
402			{"src", "a", "g", "d", "m", "report"},
403		} {
404			assertPathInsideDocument(t, mainDoc, route)
405		}
406	
407		// Promote a former intermediate to the target: report's direct edges leave
408		// the scope, while all merges feeding m remain.
409		midTarget := parseExport(t, mustExportScoped(t, graph, "src", "m"))
410		if got, want := midTarget.Nodes, []string{"a", "b", "c", "d", "g", "m", "src"}; !reflect.DeepEqual(got, want) {
411			t.Errorf("(src, m) nodes = %v, want %v", got, want)
412		}
413		if got := exportEdgeNames(midTarget); !reflect.DeepEqual(got, [][2]string{
414			{"a", "g"},
415			{"b", "c"},
416			{"b", "d"},
417			{"c", "m"},
418			{"d", "m"},
419			{"g", "d"},
420			{"g", "m"},
421			{"src", "a"},
422			{"src", "b"},
423		}) {
424			t.Errorf("(src, m) edges = %v", got)
425		}
426		for _, banned := range []string{"report", "view", "extra", "dead"} {
427			if slices.Contains(midTarget.Nodes, banned) {
428				t.Errorf("(src, m) must not include %q: %v", banned, midTarget.Nodes)
429			}
430		}
431	
432		// Promote a former intermediate to the source: the direct a -> report edge
433		// is the shortest explanation, but a -> g -> m and a -> g -> d -> m remain.
434		aSource := parseExport(t, mustExportScoped(t, graph, "a", "report"))
435		if got, want := aSource.Nodes, []string{"a", "d", "g", "m", "report"}; !reflect.DeepEqual(got, want) {
436			t.Errorf("(a, report) nodes = %v, want %v", got, want)
437		}
438		if got := exportEdgeNames(aSource); !reflect.DeepEqual(got, [][2]string{
439			{"a", "g"},
440			{"a", "report"},
441			{"d", "m"},
442			{"g", "d"},
443			{"g", "m"},
444			{"m", "report"},
445		}) {
446			t.Errorf("(a, report) edges = %v", got)
447		}
448		assertImpactOnce(t, mustImpacts(t, graph, "a"), "report", 1, []string{"a", "report"})
449		assertUpstreamOnce(t, mustUpstreams(t, graph, "report"), "a", 1, []string{"a", "report"})
450		for _, route := range [][]string{
451			{"a", "g", "m", "report"},
452			{"a", "g", "d", "m", "report"},
453		} {
454			assertPathInsideDocument(t, aSource, route)
455		}
456	
457		// Querying from the formerly "independent" source makes it a legitimate
458		// endpoint: its own routes enter the document, but src (not downstream of
459		// extra) and b/c (unreachable from extra) leave it, together with their
460		// edges into shared nodes.
461		extraDoc := parseExport(t, mustExportScoped(t, graph, "extra", "report"))
462		if got, want := extraDoc.Nodes, []string{"a", "d", "extra", "g", "m", "report"}; !reflect.DeepEqual(got, want) {
463			t.Errorf("(extra, report) nodes = %v, want %v", got, want)
464		}
465		if got := exportEdgeNames(extraDoc); !reflect.DeepEqual(got, [][2]string{
466			{"a", "g"},
467			{"a", "report"},
468			{"d", "m"},
469			{"extra", "a"},
470			{"g", "d"},
471			{"g", "m"},
472			{"m", "report"},
473		}) {
474			t.Errorf("(extra, report) edges = %v", got)
475		}
476		for _, banned := range [][2]string{{"src", "a"}, {"b", "d"}, {"c", "m"}} {
477			if slices.Contains(exportEdgeNames(extraDoc), banned) {
478				t.Errorf("(extra, report) must not carry edge %s -> %s", banned[0], banned[1])
479			}
480		}
481		assertImpactOnce(t, mustImpacts(t, graph, "extra"), "report", 2, []string{"extra", "a", "report"})
482		assertUpstreamOnce(t, mustUpstreams(t, graph, "report"), "extra", 2,
483			[]string{"extra", "a", "report"})
484	
485		// A merge whose equal-length shortest routes are tie-broken lexicographically:
486		// b -> c -> m wins over b -> d -> m (c < d), but both routes stay exported.
487		bmDoc := parseExport(t, mustExportScoped(t, graph, "b", "m"))
488		if got, want := bmDoc.Nodes, []string{"b", "c", "d", "m"}; !reflect.DeepEqual(got, want) {
489			t.Errorf("(b, m) nodes = %v, want %v", got, want)
490		}
491		if got := exportEdgeNames(bmDoc); !reflect.DeepEqual(got, [][2]string{
492			{"b", "c"},
493			{"b", "d"},
494			{"c", "m"},
495			{"d", "m"},
496		}) {
497			t.Errorf("(b, m) edges = %v", got)
498		}
499		assertImpactOnce(t, mustImpacts(t, graph, "b"), "m", 2, []string{"b", "c", "m"})
500		assertUpstreamOnce(t, mustUpstreams(t, graph, "m"), "b", 2, []string{"b", "c", "m"})
501		assertPathInsideDocument(t, bmDoc, []string{"b", "d", "m"})
502	
503		// A direct g -> m edge cannot hide the longer g -> d -> m branch, and the
504		// queries still explain via the shortest route.
505		gmDoc := parseExport(t, mustExportScoped(t, graph, "g", "m"))
506		if got, want := gmDoc.Nodes, []string{"d", "g", "m"}; !reflect.DeepEqual(got, want) {
507			t.Errorf("(g, m) nodes = %v, want %v", got, want)
508		}
509		if got := exportEdgeNames(gmDoc); !reflect.DeepEqual(got, [][2]string{
510			{"d", "m"},
511			{"g", "d"},
512			{"g", "m"},
513		}) {
514			t.Errorf("(g, m) edges = %v", got)
515		}
516		assertImpactOnce(t, mustImpacts(t, graph, "g"), "m", 1, []string{"g", "m"})
517	
518		// The target's downstream belongs to an export that actually ends there:
519		// (src, view) extends through report, while (src, report) above excludes it.
520		viewDoc := parseExport(t, mustExportScoped(t, graph, "src", "view"))
521		if got, want := viewDoc.Nodes, []string{"a", "b", "c", "d", "g", "m", "report", "src", "view"}; !reflect.DeepEqual(got, want) {
522			t.Errorf("(src, view) nodes = %v, want %v", got, want)
523		}
524		if !slices.Contains(exportEdgeNames(viewDoc), [2]string{"report", "view"}) {
525			t.Errorf("(src, view) must carry report -> view: %v", exportEdgeNames(viewDoc))
526		}
527		assertImpactOnce(t, mustImpacts(t, graph, "src"), "view", 2, []string{"src", "report", "view"})
528		assertUpstreamOnce(t, mustUpstreams(t, graph, "view"), "src", 2,
529			[]string{"src", "report", "view"})
530	
531		// A source downstream that cannot reach the target scopes to itself only.
532		deadDoc := parseExport(t, mustExportScoped(t, graph, "src", "dead"))
533		if got, want := deadDoc.Nodes, []string{"dead", "src"}; !reflect.DeepEqual(got, want) {
534			t.Errorf("(src, dead) nodes = %v, want %v", got, want)
535		}
536		if got := exportEdgeNames(deadDoc); !reflect.DeepEqual(got, [][2]string{{"src", "dead"}}) {
537			t.Errorf("(src, dead) edges = %v", got)
538		}
539	
540		// Reverse dependencies and disconnected pairs stay two empty arrays even
541		// though a real edge exists the other way, and neither query claims them.
542		for _, pair := range [][2]string{
543			{"report", "src"}, // src derives report, not the other way around
544			{"view", "report"},
545			{"m", "src"},
546			{"dead", "report"},
547			{"extra", "b"},
548			{"view", "src"}, // two hops the wrong way
549		} {
550			out := mustExportScoped(t, graph, pair[0], pair[1])
551			if want := `{"nodes":[],"edges":[]}`; out != want {
552				t.Errorf("(%q, %q) export = %s, want %s", pair[0], pair[1], out, want)
553			}
554		}
555	
556		// Identical endpoints — even a dataset with both ancestors and downstreams —
557		// export the singleton with no edges.
558		if out := mustExportScoped(t, graph, "m", "m"); out != `{"nodes":["m"],"edges":[]}` {
559			t.Errorf("(m, m) export = %s, want singleton with empty edges", out)
560		}
561	
562		if !reflect.DeepEqual(snapshot(graph), before) {
563			t.Fatalf("exports and queries changed the graph: before=%v after=%v",
564				before, snapshot(graph))
565		}
566		assertConsistent(t, graph)
567	}
