678			if len(upstreams) != 0 || upstreams == nil {
679				t.Errorf("Upstreams(%q) = %v, want non-nil empty list", name, upstreams)
680			}
681		}
682	
683		if !reflect.DeepEqual(snapshot(graph), before) {
684			t.Fatalf("boundary operations changed the graph: before=%v after=%v",
685				before, snapshot(graph))
686		}
687		assertConsistent(t, graph)
688	}
689	
690	// Public entry points, return shapes and error behavior stay compatible while
691	// the exports and queries run: missing names are rejected in source-first
692	// order with empty output, and no node, bidirectional relationship or stored
693	// list order moves.
694	func TestExportSourceTargetLineageCorrespondenceErrorsAndReadOnly(t *testing.T) {
695		graph := buildRegisteredGraph(t, correspondenceFixtureRegistrations())
696		before := snapshot(graph)
697	
698		for _, tc := range []struct {
699			name    string
700			source  string
701			target  string
702			wantErr string
703		}{
704			{"empty source", "", "report", "dataset name is required"},
705			{"empty source over missing target", "", "ghost", "dataset name is required"},
706			{"missing source first", "ghost", "phantom", "dataset not found: ghost"},
707			{"valid source then empty target", "src", "", "dataset name is required"},
708			{"valid source then missing target", "src", "ghost", "dataset not found: ghost"},
709		} {
710			t.Run(tc.name, func(t *testing.T) {
711				out, err := ExportSourceTargetLineage(graph, tc.source, tc.target)
712				if err == nil || err.Error() != tc.wantErr {
713					t.Fatalf("(%q, %q): err = %v, want %q", tc.source, tc.target, err, tc.wantErr)
714				}
715				if out != "" {
716					t.Errorf("failed export returned partial content %q", out)
717				}
718			})
719		}
720	
721		// Exercise every surface, successful and failing, then demand the exact
722		// prior graph state including parent/child list positions.
723		for _, source := range sortedGraphNames(graph) {
724			mustImpacts(t, graph, source)
725			for _, target := range sortedGraphNames(graph) {
726				mustExportScoped(t, graph, source, target)
727			}
728		}
729		for _, target := range sortedGraphNames(graph) {
730			mustUpstreams(t, graph, target)
731		}
732		if _, err := Impacts(graph, "ghost"); err == nil || !strings.Contains(err.Error(), "ghost") {
733			t.Errorf("Impacts(ghost): want error naming ghost, got %v", err)
734		}
735		if _, err := Upstreams(graph, "ghost"); err == nil || !strings.Contains(err.Error(), "ghost") {
736			t.Errorf("Upstreams(ghost): want error naming ghost, got %v", err)
737		}
738	
739		if !reflect.DeepEqual(snapshot(graph), before) {
740			t.Fatalf("operations changed the graph: before=%v after=%v", before, snapshot(graph))
741		}
742		assertConsistent(t, graph)
743	}
