1023			{
1024				{"source"},
1025				{"b", "source"}, // b-side branch registered first
1026				{"a", "source"},
1027				{"c", "b"},
1028				{"z", "a"},
1029				{"report", "c", "z"}, // c listed ahead of z on purpose
1030				{"view", "report"},
1031				{"isolated"},
1032			},
1033			{
1034				{"source"},
1035				{"a", "source"}, // opposite branch registered first
1036				{"z", "a"},
1037				{"b", "source"},
1038				{"c", "b"},
1039				{"report", "z", "c"}, // direct-upstream order flipped
1040				{"view", "report"},
1041				{"isolated"},
1042			},
1043			{
1044				{"source"},
1045				{"isolated"},
1046				{"b", "source"},
1047				{"a", "source"},
1048				{"z", "a"},
1049				{"c", "b"},
1050				{"report", "c", "z"},
1051				{"view", "report"},
1052			},
1053		}
1054	
1055		want := []Impact{
1056			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
1057			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
1058			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
1059			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
1060			{Dataset: "report", Distance: 3, Path: []string{"source", "a", "z", "report"}},
1061			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
1062		}
1063	
1064		for i, seq := range sequences {
1065			graph := buildRegisteredGraph(t, seq)
1066			assertConsistent(t, graph)
1067			before := snapshot(graph)
1068	
1069			impacts := mustImpacts(t, graph, "source")
1070			if !reflect.DeepEqual(impacts, want) {
