1072			}
1073	
1074			// Anchors with explicit messages: the merge node is explained exactly
1075			// once through a/z even though c sorts ahead of z, and view continues
1076			// along that same route.
1077			assertImpactOnce(t, impacts, "report", 3, []string{"source", "a", "z", "report"})
1078			assertImpactOnce(t, impacts, "view", 4, []string{"source", "a", "z", "report", "view"})
